# 论证层面修改：补实创新链框架、讨论增加文献对话与“证据断点”衔接段、第7章对应断点并压缩政策介绍、拆分长句
A = {}
INS = {}

A[29] = "本文以药品注册分类界定创新药。《药品注册管理办法》[21]将中药、化学药和生物制品分别划分为创新药、改良型新药等类别，《化学药品注册分类及申报资料要求》[22]将化学药品1类界定为境内外均未上市、含有新的结构明确且具有药理作用的化合物，并具有临床价值的创新药。《支持创新药高质量发展的若干措施》[2]（以下简称《若干措施》）提出增设商保创新药目录，重点纳入创新程度高、临床价值大、患者获益显著且超出基本医保保障范围的创新药。可以看出，注册分类兼顾化合物新颖性与临床价值，医保支付还考虑患者获益与保障范围。创新药上市时临床数据往往有限[15]，各方对创新的界定也不尽一致[16]，其价值判断难以在各环节间直接互认。除突破性治疗等加快上市程序[21]和商保创新药目录等专门安排外，创新药主要适用通用的药品评价规则，故本文比较三部门评价创新药所依据的政策规则，而不限于以“创新药”命名的文件。相应地，“创新药评价”指三部门政策文本中适用于创新药上市审评、医保准入和临床使用的评价规则及其关注重点，而非具体品种的评审结论。从创新链看，研发阶段形成的成果须经上市审评、医保准入和临床使用，方能转化为现实的临床价值与市场回报，这三个环节构成创新药创新链后端的制度接口[12]。各接口的评价规则决定了研发阶段需要准备何种证据，是创新主体配置研发资源的重要制度依据。据此，本文比较各环节对企业证据准备的要求，并探讨如何通过比较药品沟通、补充研究与临床应用反馈增强评价规则的可预期性。"

A[63] = "在466条核验样本中，LLM编码在安全性、有效性、经济性和公平性四个维度的{i:κ}与F1均高于规则编码，仅创新性维度规则编码略高（表3）。五维合并后，LLM编码的{i:κ}、F1与召回率分别为0.926、0.940和0.988，规则编码分别为0.765、0.799和0.690，后者仅精确率略高（0.951对0.897）。除创新性外，规则编码其余四个维度的召回率为0.629～0.689，约三成人工判为1的句段未被识别。LLM编码在经济性和公平性上的精确率相对较低（0.864和0.821），故第5.1节和第5.2节另以规则编码对照。"

A[101] = "从制度逻辑视角看，三部门关注结构的差异与其承担的决策任务相对应。药监局的科学—安全逻辑体现为对获益风险及证据充分性的重视，医保局的经济—效率逻辑体现为对相对临床价值与资源约束的关注，卫健委的公共服务逻辑则体现为对安全合理用药、药品供应与临床需求的重视。对照研究预期，药监局和医保局的结果与预期相符；卫健委安全性占比较高，但公平性占比（11.81%）与药监局（10.20%）接近，预期仅得到部分支持。这与其来源构成有关：10个来源中有7个为合理用药、处方审核和医疗质量类文件，合计占其句段的68.11%；15条公平性句段中有9条来自2024年基层药品联动管理文件。李梦颖等[17]在医保谈判药品落地环节识别出多重制度逻辑的冲突，本文则在三个主管部门的评价规则层面观察到相应分化，表明多重制度逻辑不仅存在于政策执行环节，也已嵌入各部门的评价规则之中。"

A[102] = "从注意力基础观看，关注比重与内容组合分别反映组织关注的结构与具体情境。医保局对经济性的集中关注与其基金影响报告、续约支付标准调整等任务相对应[34，49]，在含“创新药”一词的句段中经济性仍居首；其安全性与有效性的高共现表明，在准入情境中安全性多与疗效共同构成判断条件。药监局含“创新药”一词的句段则集中于创新性，服务于注册分类与研发支持。这一发现与既有国际研究相呼应。Casilli等[13]发现，跨国HTA结论差异部分源于证据质量标准的不同；本文显示，即使在同一国家内，不同部门对同一维度的证据要求亦存在系统差异。Kållberg等[15]指出的上市评价与HTA之间的证据衔接困难，在我国则表现为试验对照药、医保参照药与临床参比药之间的差异（第5.3节）。因此，关注比重的差异并不意味着部门间价值判断相互排斥，而是表明同一维度在不同环节承担着不同的决策功能。"

INS[102] = "综合上述结果，三部门关注结构的差异可归结为创新药跨环节证据衔接中的三类断点。一是比较基础断点：上市审评要求阳性对照反映目标患者的最佳治疗选择，医保准入则以目录内同类药品为参照，二者不一致时，上市证据难以直接回答医保评审中的相对临床价值问题。二是证据类型断点：药监局的关注集中于安全性与有效性（68.38%），医保局以经济性为主（76.48%），且多将安全有效作为准入前提（E|S为81.01%），上市阶段形成的获益风险证据须补充费用、基金影响与真实世界数据，方能支撑支付决策。三是应用条件断点：卫健委关注用药安全与可负担性，医保准入结论尚不足以说明药品在具体临床条件下的适用性。三类断点分别对应第7章的前置沟通、补充研究统筹与临床应用反馈三条路径。"

A[103] = "上述断点意味着，创新药在某一环节形成的评价结论进入下一环节时，需要重新说明其适用条件。医保局申报要求引用药审技术评审报告[34]，表明上市审评证据可为医保评价提供部分依据；卫健委同时评价价格与药品获取情况[31]，将支付条件与医疗机构配备、临床使用相联系。I01反映，部分药品纳入医保目录后在医疗机构的配备与使用仍然受限。因此，跨部门协同的重点不在于统一评价维度，而在于明确评价结论的适用条件，即针对同一人群核对比较药品，说明既有证据能够回答哪些问题、哪些问题有待补充研究。以适用条件为核心的协同，既保留了各部门依法履职所需的独立判断，又可减少因要求不清导致的重复论证，体现了兼顾评价质量与效率的质效协同取向。"

A[104] = "从科技创新管理视角看，评价规则的可预期性是创新主体配置研发资源的重要前提。企业设计临床研究、准备评价材料或安排补充研究时，需要掌握各环节对研究人群、对照选择、观察结果与分析视角的要求。若跨部门沟通能够尽早说明既有证据的适用范围与待补充的研究，企业即可将证据规划前移，在研发阶段统筹考虑准入与使用的需要。对于可共用的数据，可在质量要求相符的前提下统筹采集，各部门仍依据各自目的作出判断。在此意义上，跨部门协同为创新提供的“确定性”并非对评审结果的事先确定，而是对证据要求、比较基础与结论用途的明确。"

A[106] = "针对上述三类断点，本文从证据准备的前端、中间和后端提出跨部门协同路径，以增强评价规则的可预期性，促进研发—准入—使用环节的质效协同。"

A[108] = "前置沟通针对比较基础断点，是降低证据要求不确定性的前端环节。现行《参照药预沟通办法（试行）》[52]允许符合条件的1类化学药、1类治疗用生物制品及1类中成药申请推荐参照药，覆盖符合年限要求的已上市药品及上市申请已受理并通过技术评审的未上市药品，推荐结果可供企业在药物经济学或真实世界研究中选用。该机制已将比较药品沟通前置于评价研究，但尚未与上市阶段的对照选择形成衔接。"

A[109] = "本文建议从三方面加以完善。一是要求申请企业按适应症说明研究人群、治疗线别，以及试验对照药与意向医保参照药的差异和选择理由。二是结合《申报指南》[34]要求提交的药审技术评审报告，在反馈中明确既有证据可参照的范围及需补充论证的问题。三是依据2026年药品价格政策[53]对创新类别和临床价值的区分，分别说明注册分类、相对临床获益与支付评价所依据的证据。市场环境或说明书发生重大变化时，企业可重新申请；新增证据涉及原比较判断的，应说明相应变化。需要强调的是，预沟通旨在明确比较基础，申请品种仍需参加正式评审[54]，其结果不构成对准入或价格的承诺。"

A[111] = "补充研究针对证据类型断点，是衔接上市证据与支付、使用证据的中间环节。对于附条件批准等负有上市后研究义务的品种，《药品注册管理办法》[21]第六十六条要求持有人采取风险管理措施并完成研究。2025年真实世界医保综合价值评价试点通知[55]提出于2026年建设数据库、开展评价并形成初步成果，首批国家可信评价点网络已于2026年1月组建[56]；《若干措施》[2]亦推动真实世界研究结果与目录准入、续约及支付范围调整挂钩。本文建议依托上述安排，对负有上市后研究义务或支付评价证据不足的品种分别明确待回答的问题，由企业、专业评价团队与参与医疗机构共同商定研究人群、比较药品、终点、随访期限及数据质量要求。"

A[112] = "补充研究统筹的重点在于数据准备与研究安排的衔接。对于可共用的临床数据，应在使用权限、研究人群与质量要求相符的前提下协调采集字段和随访安排；药物警戒、医保价值评价与临床综合评价仍依据各自目的开展设计与分析。在分工上，医保部门按试点通知统筹组织医保评价，上市许可持有人履行法定的上市后研究义务，参与医疗机构负责数据质量与随访。研究启动前应明确结果提交时点与证据更新方式。"

A[113] = "在结果应用上，补充研究应聚焦原有证据未能回答的问题，并区分医保价值评价与药物警戒、附条件上市研究、临床综合评价的不同用途[21，31，55]。现阶段可在既有协议与权限范围内，明确新增证据用于目录续约、支付范围调整或相关评价的条件，从而在不降低评价质量要求的前提下减少重复采集，提高证据生成与使用效率。"

A[115] = "临床应用反馈针对应用条件断点，是创新药价值实现的后端环节。《若干措施》[2]已提出研究制定创新药临床综合评价技术指南、推动创新药配备使用，2025年基本医保目录与商保创新药目录发布通知[3]进一步明确了药品配备、临时采购与监测责任。本文建议在既有监测中区分药品未配备或无法使用的原因：对于证据不足的，明确后续评价需回答的问题；对于供应与支付问题，按现有职责协调解决；对于无适用患者或不具备用药条件的，不宜以提高使用量为目标。"

A[116] = "在反馈机制上，医疗机构反馈适用人群、配备状态与使用条件，企业反馈供应情况，相关部门在职责范围内核对支付与保障条件。上述信息可用于制定创新药临床综合评价技术指南及开展后续评价，并与医保评审的比较药品和证据要求相对照，识别需要补充论证的事项。需要注意的是，配备与采购信息仅反映应用条件，不能替代疗效与安全性证据；纳入商保创新药目录亦不等同于基本医保报销[3]。个体资料与保密价格信息应按授权和权限使用。由此，临床应用反馈可回流至研发端，在研发、准入与使用之间形成证据持续更新的闭环。"

A[119] = "本文的边际贡献主要有两点：一是将创新链视角引入创新药评价研究，把上市审评、医保准入与临床使用视为创新链后端的三个制度接口，在统一的五维框架下比较其关注结构，并以维度共现揭示关注比重之外的内容组合；二是从证据适用条件出发，将部门关注差异归结为比较基础、证据类型与应用条件三类证据断点，阐明跨部门协同为创新主体提供确定性的具体内涵。在实践层面，尽早明确比较药品与证据要求、统筹补充研究、利用临床应用反馈识别待研究问题，能够在保障评价质量的同时提高证据使用效率，增强评价规则对创新主体的可预期性，促进创新药研发、准入与使用环节的质效协同。"
